package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.person.Hold;

/** A claim of a person on a sheet: its amount with two decimals, its date (ISO yyyy-MM-dd), note and status
 *  (DRAFT, OPEN, PENDING — a clerk's settle above the clerk limit, awaiting a steward — SETTLED or VOID), its number on the sheet (a sheet-wide 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft; a voided claim keeps the one it had), and the due fixed when it was settled
 *  (null unless settled with a rate; its due is then worked out live from the rates), and who opened it
 *  (null until it is opened), whether its person's last statement bound it, and the figure it was bound to
 *  (null when not bound, or bound with no figure: its due then stays live), and, for a correction (a negative
 *  amount), the number of the settled claim it corrects (null otherwise), and its due-by (yyyy-MM-dd: fixed when it was
 *  created, its date then plus its person's own terms, else the terms of their grade on that date, else the sheet's terms), and
 *  whether its last statement bound it to n/a (the rate that would apply to it had ended: its due then
 *  stays n/a, not live), and the date it is deferred until (null when never deferred) and whether it is
 *  deferred now (OPEN and that date after the sheet's today: it then counts in no total, is not overdue,
 *  cannot be settled and a statement leaves it unbound), and how many proofs it has been given, and, for a claim
 *  split off another, the number of the claim it was split from (null otherwise), and whether it was a late entry
 *  (added while the period its due-by falls in was soft-closed), and the last day (the sheet's today then) a reminder
 *  was written for it (null when never reminded), and its external reference (null when none), and its tags (lower-case, sorted and
 *  comma separated, with no spaces; null when none), and the reason it was voided with (one of its sheet's void reasons; null when none was given). */
public record Claim(long id, long personId, String amount, String date, String note, String status,
        String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
        String dueBy, boolean statedNa, String deferredUntil, boolean deferred, int proofs, String splitFrom,
        boolean lateEntry, String reminded, String ref, String tags, String voidReason) {

    /** Whether the claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
    public boolean open() {
        return status.equals("OPEN") || status.equals("PENDING");
    }

    /** Whether the claim counts toward claimed and every total: only open (OPEN or PENDING) and SETTLED claims do. */
    public boolean counts() {
        return open() || status.equals("SETTLED");
    }

    /** Whether the claim counts toward live totals (claimed, due-totals, a period's total) given its
     *  person's holds: an open claim dated within a hold does not, unless a statement binds it; SETTLED
     *  claims always do. A deferred claim does not. */
    public boolean counts(List<Hold> holds) {
        return status.equals("SETTLED") || (open() && !deferred && (bound() || !Hold.anyCovers(holds, date)));
    }

    /** Whether the claim counts toward a period ending on a day, given the status it had at the end of that
     *  day (null when it did not exist then: it does not count) and its person's holds: the live rules
     *  applied to that status (an open claim deferred until after the sheet's today does not count either). A hold
     *  leaves out only a claim still open now: one since settled or voided counts by the status it had then. */
    public boolean countsAs(String statusThen, List<Hold> holds, String today) {
        if (statusThen == null) return false;
        boolean deferredNow = statusThen.equals("OPEN") && deferredUntil != null && today != null && today.compareTo(deferredUntil) < 0;
        Claim then = new Claim(id, personId, amount, date, note, statusThen, number, due, openedBy, stated, statedDue,
                corrects, dueBy, statedNa, deferredUntil, deferredNow, proofs, splitFrom, lateEntry, reminded, ref, tags, voidReason);
        return then.counts(open() ? holds : List.of());
    }

    /** Whether the claim keeps a fixed figure: its settled due, else the one its last statement bound it
     *  to — except while PENDING, when the statement does not bind it and its figure is live. */
    public boolean fixed() {
        return due != null || (bound() && statedDue != null);
    }

    /** Whether its last statement binds it now: it was stated and is not PENDING. */
    public boolean bound() {
        return stated && !status.equals("PENDING");
    }

    /** The audit field a numbered claim adds at the end of its lines: " number=<n>", or "" when it has none. */
    static String auditNumber(String number) {
        return number == null ? "" : " number=" + number;
    }

    /** The audit field a claim with an external reference adds at the end of CLAIM_ADDED: " ref=<reference>", or "" when it has none. */
    public static String auditRef(String ref) {
        return ref == null ? "" : " ref=" + ref;
    }

    /** The audit field a claim with tags adds at the end of CLAIM_ADDED: " tags=<comma separated, sorted>", or "" when it has none. */
    public static String auditTags(String tags) {
        return tags == null ? "" : " tags=" + tags;
    }

    /** Typed tags as a claim keeps them: split on commas, each trimmed and lower-cased, blanks and repeats
     *  dropped, sorted and joined with commas; null when none is left. */
    public static String tags(String typed) {
        if (typed == null) return null;
        java.util.TreeSet<String> set = new java.util.TreeSet<>();
        for (String t : typed.split(",")) {
            String tag = t.trim().toLowerCase(java.util.Locale.ROOT);
            if (!tag.isEmpty()) set.add(tag);
        }
        return set.isEmpty() ? null : String.join(",", set);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.person.WatchRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.settings.SettingsRepository;

/** A claim's status change (open, settle, approve, reject or void — a SETTLED claim too, by a steward within 7 days of its settlement), shared by the single and the bulk actions. Every
 *  check is made before anything is written, so a refusal writes nothing to the store or the audit. */
final class ClaimStatusChange {
    private ClaimStatusChange() {
    }

    static Claim apply(String id, long cid, String action, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
        return apply(id, cid, action, null, by, repository, periods, settings, audit, rollup, watches);
    }

    static Claim apply(String id, long cid, String action, String reason, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
        return apply(id, cid, action, reason, by, false, repository, periods, settings, audit, rollup, watches);
    }

    /** Make every check of the status change, writing nothing: throws the refusal the change would give. */
    static void check(String id, long cid, String action, String by, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings) throws BadRequestException {
        apply(id, cid, action, null, by, true, repository, periods, settings, null, null, null);
    }

    private static Claim apply(String id, long cid, String action, String reason, String by, boolean checkOnly, ClaimRepository repository,
            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
        if (settings.archived(id)) {
            throw new BadRequestException("the sheet is archived");
        }
        if ("resettle".equals(action == null ? "" : action.trim())) {
            return resettle(id, cid, by, repository, periods, settings, audit, rollup, watches);
        }
        String to;
        List<String> from;
        String event;
        switch (action == null ? "" : action.trim()) {
            case "open" -> { to = "OPEN"; from = List.of("DRAFT"); event = "CLAIM_OPENED"; }
            case "settle" -> { to = "SETTLED"; from = List.of("OPEN"); event = "CLAIM_SETTLED"; }
            case "approve" -> { to = "SETTLED"; from = List.of("PENDING"); event = "CLAIM_APPROVED"; }
            case "reject" -> { to = "OPEN"; from = List.of("PENDING"); event = "CLAIM_REJECTED"; }
            case "void" -> { to = "VOID"; from = List.of("DRAFT", "OPEN", "PENDING", "SETTLED"); event = "CLAIM_VOIDED"; }
            default -> throw new BadRequestException("no such action");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!from.contains(found.status())) {
            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
        }
        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
        // Open, settle and void go by the sheet's permission matrix; approve and reject stay with stewards (below).
        String act = action.trim();
        if ((act.equals("open") || act.equals("settle") || act.equals("void")) && !settings.allows(id, act, by)) {
            throw new BadRequestException("a " + settings.role(id, by) + " cannot " + act + " a claim");
        }
        // Four eyes: whoever opened a claim cannot settle it.
        if (to.equals("SETTLED") && found.status().equals("OPEN") && by.equals(found.openedBy())) {
            throw new BadRequestException("the user who opened a claim cannot settle it");
        }
        // Nor can whoever last edited it settle or approve it.
        if (to.equals("SETTLED") && (found.status().equals("OPEN") || found.status().equals("PENDING"))
                && by.equals(repository.editedBy(id, cid))) {
            throw new BadRequestException("the user who last edited a claim cannot " + act + " it");
        }
        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
        if (to.equals("SETTLED") && found.deferred()) {
            throw new BadRequestException("a claim deferred until " + found.deferredUntil() + " cannot be settled");
        }
        // Only a steward approves or rejects a PENDING claim, and never one they opened themselves.
        if (found.status().equals("PENDING") && !to.equals("VOID")) {
            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
                throw new BadRequestException("only a steward can " + action.trim() + " a pending claim");
            }
            if (to.equals("SETTLED") && by.equals(found.openedBy())) {
                throw new BadRequestException("the user who opened a claim cannot approve it");
            }
        }
        // Only a steward voids a SETTLED claim, and only within 7 days of the date its status log settled it.
        boolean reversing = found.status().equals("SETTLED") && to.equals("VOID");
        if (reversing) {
            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
                throw new BadRequestException("only a steward can void a settled claim");
            }
            Long days = repository.daysSinceSettled(id, cid);
            if (days == null || days < 0 || days > 7) {
                throw new BadRequestException("a settled claim can be voided only within 7 days of its settlement");
            }
        }
        String why = reason == null ? "" : reason.trim();
        if (event.equals("CLAIM_REJECTED") && why.isEmpty()) {
            throw new BadRequestException("give a reason to reject the claim");
        }
        // While the sheet has void reasons, a void needs one chosen from them; with none, a void takes no reason.
        String voidReason = null;
        if (to.equals("VOID")) {
            List<String> reasons = settings.voidReasons(id);
            if (!reasons.isEmpty()) {
                if (why.isEmpty()) {
                    throw new BadRequestException("choose a reason to void the claim");
                }
                if (!reasons.contains(why)) {
                    throw new BadRequestException(why + " is not one of the sheet's void reasons");
                }
                voidReason = why;
            }
        }
        // A claim whose due is above the note threshold in force on its date cannot be opened with an empty
        // note ('n/a' is above none).
        if (to.equals("OPEN") && found.status().equals("DRAFT") && (found.note() == null || found.note().trim().isEmpty())) {
            BigDecimal threshold = settings.noteThreshold(id, LocalDate.parse(found.date()));
            BigDecimal now = repository.dueNow(id, found);
            if (threshold != null && now != null && now.compareTo(threshold) > 0) {
                throw new BadRequestException("a claim with a due above the note threshold needs a note to be opened");
            }
        }
        // A claim whose due is above the proof threshold in force on its date (its person's grade's then when one
        // is set, else the sheet's) cannot be settled or approved without a proof ('n/a' is above none); this is
        // decided before the clerk limit.
        if (to.equals("SETTLED") && found.proofs() == 0) {
            BigDecimal threshold = settings.proofThreshold(id, repository.gradeOn(id, found), LocalDate.parse(found.date()));
            BigDecimal now = repository.dueNow(id, found);
            if (threshold != null && now != null && now.compareTo(threshold) > 0) {
                throw new BadRequestException("a claim with a due above the proof threshold needs a proof to be settled");
            }
        }
        // A clerk settles outright only a claim whose due is within the sheet's clerk limit ('n/a' is within
        // any); above it the claim goes to PENDING for a steward to approve or reject. A steward settles anything.
        if (to.equals("SETTLED") && found.status().equals("OPEN")
                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
            BigDecimal limit = settings.clerkLimit(id);
            BigDecimal now = repository.dueNow(id, found);
            if (limit != null && now != null && now.compareTo(limit) > 0) {
                to = "PENDING";
                event = "CLAIM_PENDING";
            }
        }
        if (checkOnly) {
            return null;
        }
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.changeStatus(id, cid, from, to)) {
            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
        }
        if (voidReason != null) {
            repository.voidReason(id, cid, voidReason);
        }
        // Opening gives the sheet's next number; a rejected claim keeps its own; a voided claim keeps the number it had (never reused).
        String number = found.number();
        String openedBy = found.openedBy();
        if (found.status().equals("DRAFT") && to.equals("OPEN")) {
            number = repository.numbersPerPeriod(id)
                    ? repository.numberInPeriod(id, cid, LocalDate.parse(found.dueBy()))
                    : repository.number(id, cid);
            repository.openedBy(id, cid, by);
            openedBy = by;
        }
        // Settling (or approving) fixes the claim's due as it is now: the figure its last statement bound it to
        // (a PENDING claim's is live), else its live due ('n/a' when its grade has no rate, which stays live), with its late charge frozen in.
        String due = null;
        String tail = event.equals("CLAIM_REJECTED") ? " reason=" + why : "";
        if (reversing) {
            tail = " reversed=" + (found.due() == null ? "n/a" : found.due());
        }
        if (voidReason != null) {
            tail += " reason=" + voidReason;
        }
        if (to.equals("SETTLED")) {
            BigDecimal now = repository.dueNow(id, found);
            repository.settleDue(id, cid, now);
            due = ClaimRepository.dueOf(now);
            tail = " due=" + (due == null ? "n/a" : due);
        }
        repository.log(id, cid, by);
        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
                number, due, openedBy, found.stated(), found.statedDue(), found.corrects(), found.dueBy(),
                found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(),
                voidReason != null ? voidReason : found.voidReason());
        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + tail);
        // A settled (or approved) claim's watchers are told, after the claim's own line and before the rollup.
        if (event.equals("CLAIM_SETTLED") || event.equals("CLAIM_APPROVED")) {
            watches.notify(id, found.personId(), repository.personName(id, found.personId()), number, by, audit);
        }
        rollup.record(id, by, before);
        return changed;
    }

    /** A steward re-settles a SETTLED claim (not in a closed period): its due is frozen again at the figure it would
     *  have today as an open claim bound by no statement (today's rates, grades, floor and late charge). */
    private static Claim resettle(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
            SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
            throw new BadRequestException("only a steward can re-settle a claim");
        }
        if (!found.status().equals("SETTLED")) {
            throw new BadRequestException("only a SETTLED claim can be re-settled");
        }
        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
        Claim live = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), "OPEN",
                found.number(), null, found.openedBy(), false, null, found.corrects(), found.dueBy(), false, null, false, found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(), found.voidReason());
        BigDecimal now = repository.dueNow(id, live);
        Rollup.Snapshot before = rollup.take(id);
        repository.settleDue(id, cid, now);
        repository.log(id, cid, by);
        String old = found.due() == null ? "n/a" : found.due();
        String due = ClaimRepository.dueOf(now);
        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(),
                found.status(), found.number(), due, found.openedBy(), found.stated(), found.statedDue(),
                found.corrects(), found.dueBy(), found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(), found.voidReason());
        audit.record("CLAIM_RESETTLED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(found.number())
                + " old=" + old + " new=" + (due == null ? "n/a" : due));
        watches.notify(id, found.personId(), repository.personName(id, found.personId()), found.number(), by, audit);
        rollup.record(id, by, before);
        return changed;
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.settings.SettingsRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/** The sheet's figures as shown: each person's claimed, due-total and overdue-total, and the sheet's
 *  claimed-total, due-total and overdue-total. A change takes them before it writes, then after its own audit lines records one ROLLUP
 *  line per person whose figures moved (people in the order they were added; a new person counts as
 *  moved), then a TOTALS line when the sheet's totals moved. */
@Service
public class Rollup {

    /** A person's figures: claimed (two decimals), due-total (two decimals, or 'n/a') and overdue-total
     *  (two decimals: the sum of the dues now of their counting claims that are overdue, skipping those with none). */
    record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
        boolean same(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /** The figures of a sheet at one moment, people by id in the order they were added. */
    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final SheetRepository sheets;
    private final SettingsRepository settings;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, SheetRepository sheets, SettingsRepository settings,
            Audit audit) {
        this.settings = settings;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now. A person's due-total is the sum of their counting claims' dues now (late charges included),
     *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
     *  then and no counting claim keeps a fixed figure or has a due (at the grade it was claimed under). A due-total is at most the sheet's cap (an 'n/a' is not capped). The sheet's due-total skips 'n/a'.
     *  The sheet's due-total and overdue-total leave out the single highest and lowest person's figure when three or more
     *  people have one. */
    public Snapshot take(String sheetId) {
        List<Person> everyone = people.list(sheetId);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        if (!everyone.isEmpty()) {
            LocalDate today = sheets.today(sheetId);
            List<Claim> all = claims.list(sheetId);
            BigDecimal cap = settings.cap(sheetId);
            for (Person p : everyone) {
                BigDecimal claimed = BigDecimal.ZERO.setScale(2);
                BigDecimal due = BigDecimal.ZERO.setScale(2);
                BigDecimal overdue = BigDecimal.ZERO.setScale(2);
                boolean fixed = false;
                for (Claim c : all) {
                    if (c.personId() != p.id() || !c.counts(p.liveHolds(today == null ? null : today.toString()))) continue;
                    claimed = claimed.add(new BigDecimal(c.amount()));
                    fixed |= c.fixed();
                    BigDecimal now = claims.dueNow(sheetId, c);
                    if (now != null) due = due.add(now);
                    if (now != null && claims.overdue(sheetId, c, today)) overdue = overdue.add(now);
                    fixed |= now != null;
                }
                boolean shown = fixed || claims.rated(sheetId, p.id(), today);
                due = SettingsRepository.capped(due, cap);
                figures.put(p.id(), new Figures(p.name(), claimed.toPlainString(),
                        shown ? due.toPlainString() : "n/a", overdue.toPlainString()));
                claimedTotal = claimedTotal.add(claimed);
                if (shown) dues.add(due);
                overdues.add(overdue);
            }
        }
        return new Snapshot(figures, claimedTotal.toPlainString(), trimmed(dues).toPlainString(),
                trimmed(overdues).toPlainString());
    }

    /** People's figures added up, leaving out the single highest and the single lowest when there are three or more. */
    static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = new ArrayList<>(figures);
        Collections.sort(sorted);
        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (BigDecimal f : sorted) total = total.add(f);
        return total;
    }

    /** Record one SNAPSHOT line per person (in the order they were added) with their due-total as {@code before} had it,
     *  ending with for=<steward> when {@code by} made the change under that steward's delegation (null when not). */
    public void snapshot(String sheetId, String by, Snapshot before, String delegator) {
        for (Figures f : before.people().values()) {
            audit.record("SNAPSHOT sheet=" + sheetId + " by=" + by + " name=" + f.name() + " due-total=" + f.dueTotal()
                    + (delegator == null ? "" : " for=" + delegator));
        }
    }

    /** Record the lines for whatever figures moved since {@code before}. */
    public void record(String sheetId, String by, Snapshot before) {
        Snapshot after = take(sheetId);
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures now = e.getValue();
            if (now.same(before.people().get(e.getKey()))) continue;
            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
                    + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
        }
        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
                || !after.overdueTotal().equals(before.overdueTotal())) {
            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
    }
