342	    public boolean remind(String sheetId, long claimId) {
343	        return jdbc.update("UPDATE claim c SET reminded = (SELECT s.today FROM sheet s WHERE s.id = c.sheet_id)"
344	                + " WHERE c.id = ? AND c.sheet_id = ? AND c.status IN ('OPEN', 'PENDING')"
345	                + " AND (c.reminded IS NULL OR c.reminded <> (SELECT s.today FROM sheet s WHERE s.id = c.sheet_id))",
346	                claimId, sheetId) > 0;
347	    }
348	
349	    /** Fix a settled claim's due. */
350	    public void settleDue(String sheetId, long claimId, BigDecimal due) {
351	        kept(sheetId, claimId, jdbc.update("UPDATE claim SET settled_due = ? WHERE id = ? AND sheet_id = ?", due, claimId, sheetId) > 0);
352	    }
353	
354	    /** The name of a person on the sheet. */
355	    public String personName(String sheetId, long personId) {
356	        return jdbc.queryForObject("SELECT name FROM person WHERE sheet_id = ? AND id = ?",
357	                String.class, sheetId, personId);
358	    }
359	
360	    /** Whether the person has a SETTLED claim with this number on the sheet. */
361	    public boolean settledOf(String sheetId, long personId, String number) {
362	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ?"
363	                + " AND claim_no = ? AND status = 'SETTLED'", Integer.class, sheetId, personId, number);
364	        return n != null && n > 0;
365	    }
366	
367	    /** The due-by of a claim created now for a person with a date: the terms-th business day after the date (skipping
368	     *  Saturdays, Sundays and the sheet's holidays), for the person's own terms, else the terms, in force on it, of the
369	     *  grade the person has on it, else the sheet's terms in force on it. */
370	    public LocalDate dueBy(String sheetId, long personId, LocalDate date) {
371	        List<Integer> mine = jdbc.queryForList("SELECT terms FROM person WHERE sheet_id = ? AND id = ?", Integer.class,
372	                sheetId, personId);
373	        if (!mine.isEmpty() && mine.get(0) != null) {
374	            return settings.businessDaysAfter(sheetId, date, mine.get(0));
375	        }
376	        List<String> grade = jdbc.queryForList("SELECT " + GRADE_ON + " FROM DUAL", String.class, sheetId, personId,
377	                date.toString());
378	        return dueByOfGrade(sheetId, grade.isEmpty() ? null : grade.get(0), date);
379	    }
380	
381	    /** The due-by of a claim created now with a date for a person of a grade (null when none) with no terms of their
382	     *  own: the terms-th business day after the date (skipping Saturdays, Sundays and the sheet's holidays), for the
383	     *  grade's terms in force on it, else the sheet's terms in force on it. */
384	    public LocalDate dueByOfGrade(String sheetId, String grade, LocalDate date) {
385	        Integer own = grade == null ? null : settings.gradeTerms(sheetId, grade, date);
386	        return settings.businessDaysAfter(sheetId, date, own != null ? own : settings.terms(sheetId, date));
387	    }
388	
389	    /** Re-fix, after a holiday is added to the sheet, the due-by of each claim not SETTLED or VOID whose due-by is on
390	     *  or after it: the terms-th business day after its date over the sheet's holidays now, for the terms it was fixed
391	     *  with (the business days from its date to its due-by over the holidays before, {@code before}). A claim whose
392	     *  due-by moves is kept in the history. */
393	    public void refixDueBy(String sheetId, java.util.Set<String> before, LocalDate holiday) {
394	        java.util.Set<String> now = new java.util.HashSet<>(before);
395	        now.add(holiday.toString());
396	        List<Object[]> open = jdbc.query("SELECT id, claim_date, due_by FROM claim WHERE sheet_id = ?"
397	                + " AND status NOT IN ('SETTLED', 'VOID') AND due_by >= ? ORDER BY id",
398	                (rs, i) -> new Object[] { rs.getLong("id"), rs.getDate("claim_date").toLocalDate(),
399	                        rs.getDate("due_by").toLocalDate() }, sheetId, Date.valueOf(holiday));
400	        for (Object[] c : open) {
401	            LocalDate date = (LocalDate) c[1];
402	            LocalDate old = (LocalDate) c[2];
403	            LocalDate fixed = SettingsRepository.businessDaysAfter(now, date, businessDaysBetween(before, date, old));
404	            if (fixed.equals(old)) continue;
405	            jdbc.update("UPDATE claim SET due_by = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(fixed), c[0], sheetId);
406	            history.claim(sheetId, (Long) c[0]);
407	        }
408	    }
409	
410	    /** The business days (not a Saturday, Sunday or one of the holidays) after a date up to and including another. */
411	    private static int businessDaysBetween(java.util.Set<String> holidays, LocalDate from, LocalDate to) {
412	        int days = 0;
413	        for (LocalDate d = from.plusDays(1); !d.isAfter(to); d = d.plusDays(1)) {
414	            java.time.DayOfWeek day = d.getDayOfWeek();
415	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY && !holidays.contains(d.toString())) {
416	                days++;
417	            }
418	        }
419	        return days;
420	    }
421	
422	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects) {
423	        return add(sheetId, personId, amount, date, note, corrects, null);
424	    }
