426	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects, String ref) {
427	        return add(sheetId, personId, amount, date, note, corrects, ref, null);
428	    }
429	
430	    /** Add a draft claim with an external reference (null: none) and tags (see {@link Claim#tags(String)}; null: none). */
431	    public Claim add(String sheetId, long personId, BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
432	        LocalDate dueBy = dueBy(sheetId, personId, date);
433	        boolean late = lateEntry(sheetId, dueBy);
434	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
435	        jdbc.update(c -> {
436	            PreparedStatement ps = c.prepareStatement(
437	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, corrects, due_by, late_entry, ref, tags) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
438	                    new String[] { "id" });
439	            ps.setString(1, sheetId);
440	            ps.setLong(2, personId);
441	            ps.setBigDecimal(3, amount);
442	            ps.setDate(4, Date.valueOf(date));
443	            ps.setString(5, note);
444	            ps.setString(6, corrects);
445	            ps.setDate(7, Date.valueOf(dueBy));
446	            ps.setBoolean(8, late);
447	            ps.setString(9, ref);
448	            ps.setString(10, tags);
449	            return ps;
450	        }, keys);
451	        kept(sheetId, keys.getKey().longValue(), true);
452	        used(sheetId, tags);
453	        return new Claim(keys.getKey().longValue(), personId, money(amount), date.toString(), note, "DRAFT", null, null, null, false, null, corrects,
454	                dueBy.toString(), false, null, false, 0, null, late, null, ref, tags, null);
455	    }
456	
457	    /** Whether a claim added now with a due-by is a late entry: the due-by falls in a soft-closed period of the sheet. */
458	    private boolean lateEntry(String sheetId, LocalDate date) {
459	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND soft_closed"
460	                + " AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, Date.valueOf(date), Date.valueOf(date));
461	        return n != null && n > 0;
462	    }
463	
464	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and is unbound from its last
465	     *  statement (live again); a new OPEN claim of the same person with the split-off amount, the same date and
466	     *  note and tags, opened by {@code by}, with its due-by fixed now and the original's number as split-from, is added
467	     *  (unnumbered: the caller numbers it; a late entry when its due-by falls in a soft-closed period). The new claim's id, or null when the sheet has no such OPEN claim. */
468	    public Long split(String sheetId, Claim claim, BigDecimal amount, String by) {
469	        BigDecimal rest = new BigDecimal(claim.amount()).subtract(amount);
470	        if (jdbc.update("UPDATE claim SET amount = ?, stated = FALSE, stated_due = NULL, stated_na = FALSE"
471	                + " WHERE id = ? AND sheet_id = ? AND status = 'OPEN'", rest, claim.id(), sheetId) == 0) {
472	            return null;
473	        }
474	        kept(sheetId, claim.id(), true);
475	        LocalDate date = LocalDate.parse(claim.date());
476	        LocalDate dueBy = dueBy(sheetId, claim.personId(), date);
477	        boolean late = lateEntry(sheetId, dueBy);
478	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
479	        jdbc.update(c -> {
480	            PreparedStatement ps = c.prepareStatement(
481	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, due_by, status, opened_by, split_from, late_entry, tags)"
482	                            + " VALUES (?, ?, ?, ?, ?, ?, 'OPEN', ?, ?, ?, ?)",
483	                    new String[] { "id" });
484	            ps.setString(1, sheetId);
485	            ps.setLong(2, claim.personId());
486	            ps.setBigDecimal(3, amount);
487	            ps.setDate(4, Date.valueOf(date));
488	            ps.setString(5, claim.note());
489	            ps.setDate(6, Date.valueOf(dueBy));
490	            ps.setString(7, by);
491	            ps.setString(8, claim.number());
492	            ps.setBoolean(9, late);
493	            ps.setString(10, claim.tags());
494	            return ps;
495	        }, keys);
496	        kept(sheetId, keys.getKey().longValue(), true);
497	        return keys.getKey().longValue();
498	    }
499	
500	    /** Change a DRAFT claim's amount, date (with the due-by it now has), note, the number it corrects, its external reference (null: none) and
501	     *  its tags (null: none); false when the sheet has no such draft claim. */
502	    public boolean update(String sheetId, long claimId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note, String corrects, String ref,
503	            String tags) {
504	        boolean changed = kept(sheetId, claimId, jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, due_by = ?, note = ?, corrects = ?, ref = ?,"
505	                + " tags = ? WHERE id = ? AND sheet_id = ? AND status = 'DRAFT'",
506	                amount, Date.valueOf(date), Date.valueOf(dueBy), note, corrects, ref, tags, claimId, sheetId) > 0);
507	        if (changed) used(sheetId, tags);
508	        return changed;
509	    }
510	
511	    /** Note tags (comma separated; null: none) as used on the sheet: each stays in {@link #tagsUsed} from now on. */
512	    private void used(String sheetId, String tags) {
513	        if (tags == null) return;
514	        for (String tag : tags.split(",")) {
515	            jdbc.update("MERGE INTO sheet_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", sheetId, tag);
516	        }
517	    }
518	
519	    /** Every tag ever used on the sheet, sorted. */
520	    public List<String> tagsUsed(String sheetId) {
521	        return jdbc.queryForList("SELECT tag FROM sheet_tag WHERE sheet_id = ? ORDER BY tag", String.class, sheetId);
522	    }
523	
524	    /** Whether an external reference is already used by a claim on the sheet other than {@code exceptId} (null: any),
525	     *  comparing without regard to case. */
