527	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND ref IS NOT NULL AND LOWER(ref) = LOWER(?)"
528	                + " AND id <> ?", Integer.class, sheetId, ref, exceptId == null ? -1L : exceptId);
529	        return n != null && n > 0;
