532	    /** Lock a claim for {@code by}'s editor, releasing any other claim of the same person {@code by} held;
533	     *  false when another user holds the claim's lock. */
534	    public boolean lock(String sheetId, Claim claim, String by) {
535	        if (jdbc.update("UPDATE claim SET locked_by = ? WHERE id = ? AND sheet_id = ?"
536	                + " AND (locked_by IS NULL OR locked_by = ?)", by, claim.id(), sheetId, by) == 0) {
537	            return false;
538	        }
539	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE sheet_id = ? AND person_id = ? AND locked_by = ? AND id <> ?",
540	                sheetId, claim.personId(), by, claim.id());
541	        return true;
542	    }
543	
544	    /** Release a claim's lock when {@code by} holds it. */
545	    public void unlock(String sheetId, long claimId, String by) {
546	        jdbc.update("UPDATE claim SET locked_by = NULL WHERE id = ? AND sheet_id = ? AND locked_by = ?", claimId, sheetId, by);
547	    }
548	
549	    /** Release every claim lock on the sheet (its today changed). */
550	    public void unlockAll(String sheetId) {
