552	    }
553	
554	    /** Who holds a claim's lock; null when it is not locked. */
555	    public String lockedBy(String sheetId, long claimId) {
556	        List<String> found = jdbc.queryForList("SELECT locked_by FROM claim WHERE id = ? AND sheet_id = ?", String.class,
557	                claimId, sheetId);
558	        return found.isEmpty() ? null : found.get(0);
559	    }
