561	    /** Make the sheet's next settle batch and give it to these claims: its number (1, 2, ... on the sheet). */
562	    public int batch(String sheetId, List<Long> claimIds) {
563	        jdbc.update("UPDATE sheet SET last_batch = COALESCE(last_batch, 0) + 1 WHERE id = ?", sheetId);
564	        int batch = lastBatch(sheetId);
565	        for (Long cid : claimIds) {
566	            jdbc.update("UPDATE claim SET batch = ? WHERE id = ? AND sheet_id = ?", batch, cid, sheetId);
567	        }
568	        return batch;
569	    }
570	
