572	    public Integer lastBatch(String sheetId) {
573	        List<Integer> found = jdbc.queryForList("SELECT last_batch FROM sheet WHERE id = ?", Integer.class, sheetId);
574	        return found.isEmpty() ? null : found.get(0);
