576	
577	    /** The settle batch of each of the sheet's claims settled by one, by claim id. */
578	    public Map<String, Integer> batches(String sheetId) {
579	        Map<String, Integer> batches = new LinkedHashMap<>();
580	        jdbc.query("SELECT id, batch FROM claim WHERE sheet_id = ? AND batch IS NOT NULL",
581	                rs -> {
582	                    batches.put(String.valueOf(rs.getLong("id")), rs.getInt("batch"));
583	                }, sheetId);
584	        return batches;
585	    }
