600	        Claim claim = find(sheetId, claimId);
601	        if (claim == null) return;
602	        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, on_date, due)"
603	                + " SELECT ?, ?, ?, ?, today, ? FROM sheet WHERE id = ?",
604	                sheetId, claimId, claim.status(), by, dueNow(sheetId, claim), sheetId);
605	    }
606	
607	    /** How many days the sheet's today is past the date a claim's status log last records it SETTLED; null when
608	     *  it records no SETTLED line. */
609	    public Long daysSinceSettled(String sheetId, long claimId) {
610	        List<Long> found = jdbc.query("SELECT DATEDIFF('DAY', l.on_date, s.today) AS days FROM claim_log l"
611	                + " JOIN sheet s ON s.id = l.sheet_id WHERE l.sheet_id = ? AND l.claim_id = ? AND l.status = 'SETTLED'"
612	                + " ORDER BY l.id DESC LIMIT 1", (rs, i) -> rs.getLong("days"), sheetId, claimId);
613	        return found.isEmpty() ? null : found.get(0);
614	    }
615	
616	    /** The status logs of the sheet's claims, by claim id: each a line per status it has had, oldest first,
617	     *  as "<STATUS> by <user> on <date> due=<due>" ('n/a' when it had no due). */
618	    public Map<String, List<String>> logs(String sheetId) {
619	        Map<String, List<String>> logs = new LinkedHashMap<>();
620	        jdbc.query("SELECT claim_id, status, by_user, on_date, due FROM claim_log WHERE sheet_id = ? ORDER BY id",
621	                rs -> {
622	                    BigDecimal due = rs.getBigDecimal("due");
623	                    logs.computeIfAbsent(String.valueOf(rs.getLong("claim_id")), k -> new ArrayList<>())
624	                            .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
625	                                    + rs.getDate("on_date").toLocalDate() + " due=" + (due == null ? "n/a" : money(due)));
626	                }, sheetId);
627	        return logs;
628	    }
629	
630	    /** Keep a comment on a claim: its text, who wrote it and the sheet's today. */
631	    public void comment(String sheetId, long claimId, String by, String text) {
632	        jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, on_date, text)"
633	                + " SELECT ?, ?, ?, today, ? FROM sheet WHERE id = ?", sheetId, claimId, by, text, sheetId);
634	    }
635	
636	    /** The comments of the sheet's claims, by claim id: each oldest first, as "<user> on <date>: <text>". */
637	    public Map<String, List<String>> comments(String sheetId) {
638	        Map<String, List<String>> comments = new LinkedHashMap<>();
639	        jdbc.query("SELECT claim_id, by_user, on_date, text FROM claim_comment WHERE sheet_id = ? ORDER BY id",
640	                rs -> {
641	                    comments.computeIfAbsent(String.valueOf(rs.getLong("claim_id")), k -> new ArrayList<>())
642	                            .add(rs.getString("by_user") + " on " + rs.getDate("on_date").toLocalDate() + ": " + rs.getString("text"));
643	                }, sheetId);
644	        return comments;
645	    }
646	
647	    /** Each claim's status at the end of a day, by claim id, as its status log records it: the last line
648	     *  dated on or before it. A claim with no such line (added after that day) is absent. */
649	    public Map<Long, String> statusesOn(String sheetId, LocalDate day) {
650	        Map<Long, String> statuses = new LinkedHashMap<>();
651	        jdbc.query("SELECT claim_id, status FROM claim_log WHERE sheet_id = ? AND on_date <= ? ORDER BY id",
652	                rs -> {
653	                    statuses.put(rs.getLong("claim_id"), rs.getString("status"));
654	                }, sheetId, Date.valueOf(day));
655	        return statuses;
656	    }
