658	    /** An amount as shown: two decimals, a dot, no grouping. */
659	    static String money(BigDecimal amount) {
660	        return amount.setScale(2).toPlainString();
661	    }
662	
663	    /** A fixed due as shown, or null when there is none. */
664	    static String dueOf(BigDecimal due) {
665	        return due == null ? null : money(due);
666	    }
667	}
