                + " WHERE c.id = ? AND c.sheet_id = ? AND c.status IN ('OPEN', 'PENDING')"
                + " AND (c.reminded IS NULL OR c.reminded <> (SELECT s.today FROM sheet s WHERE s.id = c.sheet_id))",
                claimId, sheetId) > 0;
