1	package net.officefloor.hq.app.claim;
2	
3	import java.util.List;
4	import net.officefloor.hq.app.person.Hold;
5	
6	/** A claim of a person on a sheet: its amount with two decimals, its date (ISO yyyy-MM-dd), note and status
7	 *  (DRAFT, OPEN, PENDING — a clerk's settle above the clerk limit, awaiting a steward — SETTLED or VOID), its number on the sheet (a sheet-wide 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft; a voided claim keeps the one it had), and the due fixed when it was settled
8	 *  (null unless settled with a rate; its due is then worked out live from the rates), and who opened it
9	 *  (null until it is opened), whether its person's last statement bound it, and the figure it was bound to
10	 *  (null when not bound, or bound with no figure: its due then stays live), and, for a correction (a negative
11	 *  amount), the number of the settled claim it corrects (null otherwise), and its due-by (yyyy-MM-dd: fixed when it was
12	 *  created, its date then plus its person's own terms, else the terms of their grade on that date, else the sheet's terms), and
13	 *  whether its last statement bound it to n/a (the rate that would apply to it had ended: its due then
14	 *  stays n/a, not live), and the date it is deferred until (null when never deferred) and whether it is
15	 *  deferred now (OPEN and that date after the sheet's today: it then counts in no total, is not overdue,
16	 *  cannot be settled and a statement leaves it unbound), and how many proofs it has been given, and, for a claim
17	 *  split off another, the number of the claim it was split from (null otherwise), and whether it was a late entry
18	 *  (added while the period its due-by falls in was soft-closed), and the last day (the sheet's today then) a reminder
19	 *  was written for it (null when never reminded), and its external reference (null when none), and its tags (lower-case, sorted and
20	 *  comma separated, with no spaces; null when none), and the reason it was voided with (one of its sheet's void reasons; null when none was given). */
21	public record Claim(long id, long personId, String amount, String date, String note, String status,
22	        String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
23	        String dueBy, boolean statedNa, String deferredUntil, boolean deferred, int proofs, String splitFrom,
24	        boolean lateEntry, String reminded, String ref, String tags, String voidReason) {
25	
26	    /** Whether the claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
27	    public boolean open() {
28	        return status.equals("OPEN") || status.equals("PENDING");
29	    }
30	
31	    /** Whether the claim counts toward claimed and every total: only open (OPEN or PENDING) and SETTLED claims do. */
32	    public boolean counts() {
33	        return open() || status.equals("SETTLED");
34	    }
35	
36	    /** Whether the claim counts toward live totals (claimed, due-totals, a period's total) given its
37	     *  person's holds: an open claim dated within a hold does not, unless a statement binds it; SETTLED
38	     *  claims always do. A deferred claim does not. */
39	    public boolean counts(List<Hold> holds) {
40	        return status.equals("SETTLED") || (open() && !deferred && (bound() || !Hold.anyCovers(holds, date)));
41	    }
42	
43	    /** Whether the claim counts toward a period ending on a day, given the status it had at the end of that
44	     *  day (null when it did not exist then: it does not count) and its person's holds: the live rules
45	     *  applied to that status (an open claim deferred until after the sheet's today does not count either). A hold
46	     *  leaves out only a claim still open now: one since settled or voided counts by the status it had then. */
47	    public boolean countsAs(String statusThen, List<Hold> holds, String today) {
48	        if (statusThen == null) return false;
49	        boolean deferredNow = statusThen.equals("OPEN") && deferredUntil != null && today != null && today.compareTo(deferredUntil) < 0;
50	        Claim then = new Claim(id, personId, amount, date, note, statusThen, number, due, openedBy, stated, statedDue,
51	                corrects, dueBy, statedNa, deferredUntil, deferredNow, proofs, splitFrom, lateEntry, reminded, ref, tags, voidReason);
52	        return then.counts(open() ? holds : List.of());
53	    }
54	
55	    /** Whether the claim keeps a fixed figure: its settled due, else the one its last statement bound it
56	     *  to — except while PENDING, when the statement does not bind it and its figure is live. */
57	    public boolean fixed() {
58	        return due != null || (bound() && statedDue != null);
59	    }
60	
61	    /** Whether its last statement binds it now: it was stated and is not PENDING. */
62	    public boolean bound() {
63	        return stated && !status.equals("PENDING");
64	    }
65	
66	    /** The audit field a numbered claim adds at the end of its lines: " number=<n>", or "" when it has none. */
67	    static String auditNumber(String number) {
68	        return number == null ? "" : " number=" + number;
69	    }
70	
71	    /** The audit field a claim with an external reference adds at the end of CLAIM_ADDED: " ref=<reference>", or "" when it has none. */
72	    public static String auditRef(String ref) {
73	        return ref == null ? "" : " ref=" + ref;
74	    }
75	
76	    /** The audit field a claim with tags adds at the end of CLAIM_ADDED: " tags=<comma separated, sorted>", or "" when it has none. */
77	    public static String auditTags(String tags) {
78	        return tags == null ? "" : " tags=" + tags;
79	    }
80	
81	    /** Typed tags as a claim keeps them: split on commas, each trimmed and lower-cased, blanks and repeats
82	     *  dropped, sorted and joined with commas; null when none is left. */
83	    public static String tags(String typed) {
84	        if (typed == null) return null;
85	        java.util.TreeSet<String> set = new java.util.TreeSet<>();
86	        for (String t : typed.split(",")) {
87	            String tag = t.trim().toLowerCase(java.util.Locale.ROOT);
88	            if (!tag.isEmpty()) set.add(tag);
89	        }
90	        return set.isEmpty() ? null : String.join(",", set);
91	    }
92	}
93	package net.officefloor.hq.app.claim;
94	
95	import java.math.BigDecimal;
96	import java.time.LocalDate;
97	import java.util.List;
98	import net.officefloor.hq.app.Audit;
99	import net.officefloor.hq.app.BadRequestException;
100	import net.officefloor.hq.app.period.PeriodGuard;
101	import net.officefloor.hq.app.person.WatchRepository;
102	import net.officefloor.hq.app.period.PeriodRepository;
103	import net.officefloor.hq.app.rollup.Rollup;
104	import net.officefloor.hq.app.settings.SettingsRepository;
105	
106	/** A claim's status change (open, settle, approve, reject or void — a SETTLED claim too, by a steward within 7 days of its settlement), shared by the single and the bulk actions. Every
107	 *  check is made before anything is written, so a refusal writes nothing to the store or the audit. */
108	final class ClaimStatusChange {
109	    private ClaimStatusChange() {
110	    }
111	
112	    static Claim apply(String id, long cid, String action, String by, ClaimRepository repository,
113	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
114	        return apply(id, cid, action, null, by, repository, periods, settings, audit, rollup, watches);
115	    }
116	
117	    static Claim apply(String id, long cid, String action, String reason, String by, ClaimRepository repository,
118	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
119	        return apply(id, cid, action, reason, by, false, repository, periods, settings, audit, rollup, watches);
120	    }
121	
122	    /** Make every check of the status change, writing nothing: throws the refusal the change would give. */
123	    static void check(String id, long cid, String action, String by, ClaimRepository repository,
124	            PeriodRepository periods, SettingsRepository settings) throws BadRequestException {
125	        apply(id, cid, action, null, by, true, repository, periods, settings, null, null, null);
126	    }
127	
128	    private static Claim apply(String id, long cid, String action, String reason, String by, boolean checkOnly, ClaimRepository repository,
129	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
130	        if (settings.archived(id)) {
131	            throw new BadRequestException("the sheet is archived");
132	        }
133	        if ("resettle".equals(action == null ? "" : action.trim())) {
134	            return resettle(id, cid, by, repository, periods, settings, audit, rollup, watches);
135	        }
136	        String to;
137	        List<String> from;
138	        String event;
139	        switch (action == null ? "" : action.trim()) {
140	            case "open" -> { to = "OPEN"; from = List.of("DRAFT"); event = "CLAIM_OPENED"; }
141	            case "settle" -> { to = "SETTLED"; from = List.of("OPEN"); event = "CLAIM_SETTLED"; }
142	            case "approve" -> { to = "SETTLED"; from = List.of("PENDING"); event = "CLAIM_APPROVED"; }
143	            case "reject" -> { to = "OPEN"; from = List.of("PENDING"); event = "CLAIM_REJECTED"; }
144	            case "void" -> { to = "VOID"; from = List.of("DRAFT", "OPEN", "PENDING", "SETTLED"); event = "CLAIM_VOIDED"; }
145	            default -> throw new BadRequestException("no such action");
146	        }
147	        Claim found = repository.find(id, cid);
148	        if (found == null) {
149	            throw new BadRequestException("no such claim");
150	        }
151	        if (!from.contains(found.status())) {
152	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
153	        }
154	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
155	        // Open, settle and void go by the sheet's permission matrix; approve and reject stay with stewards (below).
156	        String act = action.trim();
157	        if ((act.equals("open") || act.equals("settle") || act.equals("void")) && !settings.allows(id, act, by)) {
158	            throw new BadRequestException("a " + settings.role(id, by) + " cannot " + act + " a claim");
159	        }
160	        // Four eyes: whoever opened a claim cannot settle it.
161	        if (to.equals("SETTLED") && found.status().equals("OPEN") && by.equals(found.openedBy())) {
162	            throw new BadRequestException("the user who opened a claim cannot settle it");
163	        }
164	        // Nor can whoever last edited it settle or approve it.
165	        if (to.equals("SETTLED") && (found.status().equals("OPEN") || found.status().equals("PENDING"))
166	                && by.equals(repository.editedBy(id, cid))) {
167	            throw new BadRequestException("the user who last edited a claim cannot " + act + " it");
168	        }
169	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
170	        if (to.equals("SETTLED") && found.deferred()) {
171	            throw new BadRequestException("a claim deferred until " + found.deferredUntil() + " cannot be settled");
172	        }
173	        // Only a steward approves or rejects a PENDING claim, and never one they opened themselves.
174	        if (found.status().equals("PENDING") && !to.equals("VOID")) {
175	            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
176	                throw new BadRequestException("only a steward can " + action.trim() + " a pending claim");
177	            }
178	            if (to.equals("SETTLED") && by.equals(found.openedBy())) {
179	                throw new BadRequestException("the user who opened a claim cannot approve it");
180	            }
181	        }
182	        // Only a steward voids a SETTLED claim, and only within 7 days of the date its status log settled it.
183	        boolean reversing = found.status().equals("SETTLED") && to.equals("VOID");
184	        if (reversing) {
185	            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
186	                throw new BadRequestException("only a steward can void a settled claim");
187	            }
188	            Long days = repository.daysSinceSettled(id, cid);
189	            if (days == null || days < 0 || days > 7) {
190	                throw new BadRequestException("a settled claim can be voided only within 7 days of its settlement");
191	            }
192	        }
193	        String why = reason == null ? "" : reason.trim();
194	        if (event.equals("CLAIM_REJECTED") && why.isEmpty()) {
195	            throw new BadRequestException("give a reason to reject the claim");
196	        }
197	        // While the sheet has void reasons, a void needs one chosen from them; with none, a void takes no reason.
198	        String voidReason = null;
199	        if (to.equals("VOID")) {
200	            List<String> reasons = settings.voidReasons(id);
201	            if (!reasons.isEmpty()) {
202	                if (why.isEmpty()) {
203	                    throw new BadRequestException("choose a reason to void the claim");
204	                }
205	                if (!reasons.contains(why)) {
206	                    throw new BadRequestException(why + " is not one of the sheet's void reasons");
207	                }
208	                voidReason = why;
209	            }
210	        }
211	        // A claim whose due is above the note threshold in force on its date cannot be opened with an empty
212	        // note ('n/a' is above none).
213	        if (to.equals("OPEN") && found.status().equals("DRAFT") && (found.note() == null || found.note().trim().isEmpty())) {
214	            BigDecimal threshold = settings.noteThreshold(id, LocalDate.parse(found.date()));
215	            BigDecimal now = repository.dueNow(id, found);
216	            if (threshold != null && now != null && now.compareTo(threshold) > 0) {
217	                throw new BadRequestException("a claim with a due above the note threshold needs a note to be opened");
218	            }
219	        }
220	        // A claim whose due is above the proof threshold in force on its date (its person's grade's then when one
221	        // is set, else the sheet's) cannot be settled or approved without a proof ('n/a' is above none); this is
222	        // decided before the clerk limit.
223	        if (to.equals("SETTLED") && found.proofs() == 0) {
224	            BigDecimal threshold = settings.proofThreshold(id, repository.gradeOn(id, found), LocalDate.parse(found.date()));
225	            BigDecimal now = repository.dueNow(id, found);
226	            if (threshold != null && now != null && now.compareTo(threshold) > 0) {
227	                throw new BadRequestException("a claim with a due above the proof threshold needs a proof to be settled");
228	            }
229	        }
230	        // A clerk settles outright only a claim whose due is within the sheet's clerk limit ('n/a' is within
231	        // any); above it the claim goes to PENDING for a steward to approve or reject. A steward settles anything.
232	        if (to.equals("SETTLED") && found.status().equals("OPEN")
233	                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
234	            BigDecimal limit = settings.clerkLimit(id);
235	            BigDecimal now = repository.dueNow(id, found);
236	            if (limit != null && now != null && now.compareTo(limit) > 0) {
237	                to = "PENDING";
238	                event = "CLAIM_PENDING";
239	            }
240	        }
241	        if (checkOnly) {
242	            return null;
243	        }
244	        Rollup.Snapshot before = rollup.take(id);
245	        if (!repository.changeStatus(id, cid, from, to)) {
246	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
247	        }
248	        if (voidReason != null) {
249	            repository.voidReason(id, cid, voidReason);
250	        }
251	        // Opening gives the sheet's next number; a rejected claim keeps its own; a voided claim keeps the number it had (never reused).
252	        String number = found.number();
253	        String openedBy = found.openedBy();
254	        if (found.status().equals("DRAFT") && to.equals("OPEN")) {
255	            number = repository.numbersPerPeriod(id)
256	                    ? repository.numberInPeriod(id, cid, LocalDate.parse(found.dueBy()))
257	                    : repository.number(id, cid);
258	            repository.openedBy(id, cid, by);
259	            openedBy = by;
260	        }
261	        // Settling (or approving) fixes the claim's due as it is now: the figure its last statement bound it to
262	        // (a PENDING claim's is live), else its live due ('n/a' when its grade has no rate, which stays live), with its late charge frozen in.
263	        String due = null;
264	        String tail = event.equals("CLAIM_REJECTED") ? " reason=" + why : "";
265	        if (reversing) {
266	            tail = " reversed=" + (found.due() == null ? "n/a" : found.due());
267	        }
268	        if (voidReason != null) {
269	            tail += " reason=" + voidReason;
270	        }
271	        if (to.equals("SETTLED")) {
272	            BigDecimal now = repository.dueNow(id, found);
273	            repository.settleDue(id, cid, now);
274	            due = ClaimRepository.dueOf(now);
275	            tail = " due=" + (due == null ? "n/a" : due);
276	        }
277	        repository.log(id, cid, by);
278	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
279	                number, due, openedBy, found.stated(), found.statedDue(), found.corrects(), found.dueBy(),
280	                found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(),
281	                voidReason != null ? voidReason : found.voidReason());
282	        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
283	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + tail);
284	        // A settled (or approved) claim's watchers are told, after the claim's own line and before the rollup.
285	        if (event.equals("CLAIM_SETTLED") || event.equals("CLAIM_APPROVED")) {
286	            watches.notify(id, found.personId(), repository.personName(id, found.personId()), number, by, audit);
287	        }
288	        rollup.record(id, by, before);
289	        return changed;
290	    }
291	
292	    /** A steward re-settles a SETTLED claim (not in a closed period): its due is frozen again at the figure it would
293	     *  have today as an open claim bound by no statement (today's rates, grades, floor and late charge). */
294	    private static Claim resettle(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
295	            SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches) throws BadRequestException {
296	        Claim found = repository.find(id, cid);
297	        if (found == null) {
298	            throw new BadRequestException("no such claim");
299	        }
300	        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
301	            throw new BadRequestException("only a steward can re-settle a claim");
302	        }
303	        if (!found.status().equals("SETTLED")) {
304	            throw new BadRequestException("only a SETTLED claim can be re-settled");
305	        }
306	        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
307	        Claim live = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), "OPEN",
308	                found.number(), null, found.openedBy(), false, null, found.corrects(), found.dueBy(), false, null, false, found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(), found.voidReason());
309	        BigDecimal now = repository.dueNow(id, live);
310	        Rollup.Snapshot before = rollup.take(id);
311	        repository.settleDue(id, cid, now);
312	        repository.log(id, cid, by);
313	        String old = found.due() == null ? "n/a" : found.due();
314	        String due = ClaimRepository.dueOf(now);
315	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(),
316	                found.status(), found.number(), due, found.openedBy(), found.stated(), found.statedDue(),
317	                found.corrects(), found.dueBy(), found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), found.ref(), found.tags(), found.voidReason());
318	        audit.record("CLAIM_RESETTLED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
319	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(found.number())
320	                + " old=" + old + " new=" + (due == null ? "n/a" : due));
321	        watches.notify(id, found.personId(), repository.personName(id, found.personId()), found.number(), by, audit);
322	        rollup.record(id, by, before);
323	        return changed;
324	    }
325	}
