341	import net.officefloor.hq.app.sheet.SheetRepository;
342	import org.springframework.stereotype.Service;
343	
344	/** The sheet's figures as shown: each person's claimed, due-total and overdue-total, and the sheet's
345	 *  claimed-total, due-total and overdue-total. A change takes them before it writes, then after its own audit lines records one ROLLUP
346	 *  line per person whose figures moved (people in the order they were added; a new person counts as
347	 *  moved), then a TOTALS line when the sheet's totals moved. */
348	@Service
349	public class Rollup {
350	
351	    /** A person's figures: claimed (two decimals), due-total (two decimals, or 'n/a') and overdue-total
352	     *  (two decimals: the sum of the dues now of their counting claims that are overdue, skipping those with none). */
353	    record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
354	        boolean same(Figures other) {
355	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
356	                    && overdueTotal.equals(other.overdueTotal);
357	        }
358	    }
359	
360	    /** The figures of a sheet at one moment, people by id in the order they were added. */
361	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
362	    }
363	
364	    private final PersonRepository people;
365	    private final ClaimRepository claims;
366	    private final SheetRepository sheets;
367	    private final SettingsRepository settings;
368	    private final Audit audit;
369	
370	    public Rollup(PersonRepository people, ClaimRepository claims, SheetRepository sheets, SettingsRepository settings,
371	            Audit audit) {
372	        this.settings = settings;
373	        this.people = people;
374	        this.claims = claims;
375	        this.sheets = sheets;
376	        this.audit = audit;
377	    }
378	
379	    /** The sheet's figures now. A person's due-total is the sum of their counting claims' dues now (late charges included),
380	     *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
381	     *  then and no counting claim keeps a fixed figure or has a due (at the grade it was claimed under). A due-total is at most the sheet's cap (an 'n/a' is not capped). The sheet's due-total skips 'n/a'.
382	     *  The sheet's due-total and overdue-total leave out the single highest and lowest person's figure when three or more
383	     *  people have one. */
384	    public Snapshot take(String sheetId) {
385	        List<Person> everyone = people.list(sheetId);
386	        Map<Long, Figures> figures = new LinkedHashMap<>();
387	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
388	        List<BigDecimal> dues = new ArrayList<>();
389	        List<BigDecimal> overdues = new ArrayList<>();
390	        if (!everyone.isEmpty()) {
391	            LocalDate today = sheets.today(sheetId);
392	            List<Claim> all = claims.list(sheetId);
393	            BigDecimal cap = settings.cap(sheetId);
394	            for (Person p : everyone) {
395	                BigDecimal claimed = BigDecimal.ZERO.setScale(2);
396	                BigDecimal due = BigDecimal.ZERO.setScale(2);
397	                BigDecimal overdue = BigDecimal.ZERO.setScale(2);
398	                boolean fixed = false;
399	                for (Claim c : all) {
400	                    if (c.personId() != p.id() || !c.counts(p.liveHolds(today == null ? null : today.toString()))) continue;
401	                    claimed = claimed.add(new BigDecimal(c.amount()));
402	                    fixed |= c.fixed();
403	                    BigDecimal now = claims.dueNow(sheetId, c);
404	                    if (now != null) due = due.add(now);
405	                    if (now != null && claims.overdue(sheetId, c, today)) overdue = overdue.add(now);
406	                    fixed |= now != null;
407	                }
408	                boolean shown = fixed || claims.rated(sheetId, p.id(), today);
409	                due = SettingsRepository.capped(due, cap);
410	                figures.put(p.id(), new Figures(p.name(), claimed.toPlainString(),
411	                        shown ? due.toPlainString() : "n/a", overdue.toPlainString()));
412	                claimedTotal = claimedTotal.add(claimed);
413	                if (shown) dues.add(due);
414	                overdues.add(overdue);
415	            }
416	        }
417	        return new Snapshot(figures, claimedTotal.toPlainString(), trimmed(dues).toPlainString(),
418	                trimmed(overdues).toPlainString());
419	    }
420	
421	    /** People's figures added up, leaving out the single highest and the single lowest when there are three or more. */
422	    static BigDecimal trimmed(List<BigDecimal> figures) {
423	        List<BigDecimal> sorted = new ArrayList<>(figures);
424	        Collections.sort(sorted);
425	        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
426	        BigDecimal total = BigDecimal.ZERO.setScale(2);
427	        for (BigDecimal f : sorted) total = total.add(f);
428	        return total;
429	    }
430	
431	    /** Record one SNAPSHOT line per person (in the order they were added) with their due-total as {@code before} had it,
432	     *  ending with for=<steward> when {@code by} made the change under that steward's delegation (null when not). */
433	    public void snapshot(String sheetId, String by, Snapshot before, String delegator) {
434	        for (Figures f : before.people().values()) {
435	            audit.record("SNAPSHOT sheet=" + sheetId + " by=" + by + " name=" + f.name() + " due-total=" + f.dueTotal()
436	                    + (delegator == null ? "" : " for=" + delegator));
437	        }
438	    }
439	
440	    /** Record the lines for whatever figures moved since {@code before}. */
441	    public void record(String sheetId, String by, Snapshot before) {
442	        Snapshot after = take(sheetId);
443	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
444	            Figures now = e.getValue();
445	            if (now.same(before.people().get(e.getKey()))) continue;
446	            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
447	                    + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
448	        }
449	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
450	                || !after.overdueTotal().equals(before.overdueTotal())) {
451	            audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + after.claimedTotal()
452	                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
453	        }
454	    }
455	}
