513	/** Bind the claim form: an amount is required (a number with up to two decimals; a negative one is a
514	 *  correction), a blank date takes the sheet's entry date (its today when none is set), the note may be empty, and corrects is blank or
515	 *  the number of the claim a correction corrects, and the external reference is trimmed (blank: none), and the tags are kept as {@link Claim#tags(String)} has them. */
516	public class ValidateClaim {
517	    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> claim) throws BadRequestException {
518	        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
519	        String date = request == null || request.date() == null ? "" : request.date().trim();
520	        String note = request == null || request.note() == null ? "" : request.note().trim();
521	        String corrects = request == null || request.corrects() == null ? "" : request.corrects().trim();
522	        String number = corrects.isEmpty() ? null : corrects;
523	        String ref = request == null || request.ref() == null ? "" : request.ref().trim();
524	        LocalDate on = null;
