538	import java.math.BigDecimal;
539	import java.time.LocalDate;
540	import java.util.regex.Pattern;
541	import net.officefloor.hq.app.BadRequestException;
542	
543	/** A validated claim form: the amount (negative for a correction), the date ({@code null} when left blank:
544	 *  the sheet's today), the note, and the number of the claim a correction corrects ({@code null} when left blank), and its external reference (trimmed;
545	 *  {@code null} when left blank), and its tags (see {@link Claim#tags(String)}; {@code null} when none). */
546	public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
547	
548	    private static final Pattern SIGNED = Pattern.compile("-?(\\d+(\\.\\d{1,2})?|\\.\\d{1,2})");
549	
550	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?|\\.\\d{1,2}");
551	
552	    /** A typed amount (trimmed): required, a number with up to two decimals, 0.00 or more. */
553	    public static BigDecimal amount(String amount) throws BadRequestException {
554	        if (amount.isEmpty()) {
555	            throw new BadRequestException("amount is required");
556	        }
557	        if (!AMOUNT.matcher(amount).matches()) {
558	            throw new BadRequestException("amount must be a number of 0.00 or more with up to two decimals");
559	        }
560	        return new BigDecimal(amount).setScale(2);
561	    }
562	
563	    /** A typed claim-form amount (trimmed): required, a number with up to two decimals; a negative one
564	     *  is a correction. */
565	    public static BigDecimal signedAmount(String amount) throws BadRequestException {
566	        if (amount.isEmpty()) {
567	            throw new BadRequestException("amount is required");
568	        }
569	        if (!SIGNED.matcher(amount).matches()) {
570	            throw new BadRequestException("amount must be a number with up to two decimals");
571	        }
572	        return new BigDecimal(amount).setScale(2);
573	    }
574	
575	    /** Check the external reference against the sheet: one already used by another claim on it (other than
576	     *  {@code exceptId}, null: none), comparing without regard to case, is refused. */
577	    public void checkRef(ClaimRepository repository, String sheetId, Long exceptId) throws BadRequestException {
578	        if (ref != null && repository.refUsed(sheetId, ref, exceptId)) {
579	            throw new BadRequestException("reference " + ref + " is already used on the sheet");
580	        }
581	    }
582	
583	    /** Whether the amount is a correction's: below zero. */
584	    public boolean correction() {
585	        return amount.signum() < 0;
586	    }
587	
588	    /** Check the form against the person's claims: a negative amount must name, by number, a SETTLED
589	     *  claim of the same person; only a negative amount may name one. */
590	    public void checkCorrection(ClaimRepository repository, String sheetId, long personId) throws BadRequestException {
591	        if (!correction()) {
592	            if (corrects != null) {
593	                throw new BadRequestException("only a negative amount corrects a claim");
594	            }
595	            return;
596	        }
597	        if (corrects == null) {
598	            throw new BadRequestException("a negative amount is a correction: name the settled claim it corrects");
599	        }
600	        if (!repository.settledOf(sheetId, personId, corrects)) {
601	            throw new BadRequestException("claim " + corrects + " is not a settled claim of this person");
602	        }
603	    }
604	}
