332	    /** The terms-th business day after a date, skipping every Saturday, Sunday and one of the holidays (yyyy-MM-dd). */
333	    public static LocalDate businessDaysAfter(java.util.Set<String> holidays, LocalDate date, int terms) {
334	        int counted = 0;
335	        while (counted < terms) {
336	            date = date.plusDays(1);
337	            java.time.DayOfWeek day = date.getDayOfWeek();
338	            if (day != java.time.DayOfWeek.SATURDAY && day != java.time.DayOfWeek.SUNDAY
339	                    && !holidays.contains(date.toString())) {
340	                counted++;
341	            }
342	        }
343	        return date;
344	    }
