379	     *  standing rule (open, settle, void and close by clerk and steward; reassign and reopen by steward). */
380	    public boolean allows(String sheetId, String action, String user) {
381	        List<String> found = jdbc.query("SELECT roles FROM sheet_permission WHERE sheet_id = ? AND action = ?",
382	                (rs, i) -> rs.getString("roles"), sheetId, action);
383	        List<String> roles = found.isEmpty()
384	                ? (action.equals("reassign") || action.equals("reopen") ? List.of(STEWARD) : List.of(CLERK, STEWARD))
385	                : List.of(found.get(0).split(","));
386	        return roles.contains(role(sheetId, user));
