479	    public List<GradeFrom> grades(String sheetId, long id) {
480	        return jdbc.query("SELECT grade, from_date FROM person_grade WHERE sheet_id = ? AND person_id = ?"
481	                + " ORDER BY from_date NULLS FIRST", (rs, i) -> gradeFrom(rs), sheetId, id);
482	    }
483	
484	    /** Give a person a grade from a from-date (null: from the beginning of time), replacing the one
485	     *  they had from that date. */
486	    public void grade(String sheetId, long id, String grade, LocalDate from) {
487	        Date on = from == null ? null : Date.valueOf(from);
488	        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date IS NOT DISTINCT FROM ?",
489	                sheetId, id, on);
490	        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date) VALUES (?, ?, ?, ?)",
491	                sheetId, id, grade, on);
492	        history.grade(sheetId, id, grade, from);
493	    }
494	
495	    /** A person on the sheet; null when the sheet has no such person. */
496	    public Person find(String sheetId, long id) {
497	        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?", ROW,
498	                sheetId, id);
499	        return found.isEmpty() ? null : found.get(0).withGrades(grades(sheetId, id)).withHolds(holds(sheetId, id));
500	    }
501	
502	    /** Record a statement taken of a person: one more, with its due-total and date. */
503	    public void stated(String sheetId, long id, String total, LocalDate date) {
504	        jdbc.update("UPDATE person SET statement_count = statement_count + 1, stated_total = ?, statement_date = ?"
505	                + " WHERE id = ? AND sheet_id = ?", total, Date.valueOf(date), id, sheetId);
506	        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, seq, due_total, statement_date)"
507	                + " SELECT sheet_id, id, statement_count, stated_total, statement_date FROM person WHERE id = ? AND sheet_id = ?",
508	                id, sheetId);
509	    }
510	
511	    /** Cancel a person's last statement: one fewer, showing the due-total and date of the one before it
512	     *  (none when it was the first, or was taken before statements were kept). */
513	    public void unstated(String sheetId, long id) {
514	        jdbc.update("DELETE FROM person_statement WHERE sheet_id = ? AND person_id = ?"
515	                + " AND seq = (SELECT statement_count FROM person WHERE id = ? AND sheet_id = ?)", sheetId, id, id, sheetId);
516	        jdbc.update("UPDATE person SET statement_count = statement_count - 1,"
517	                + " stated_total = (SELECT s.due_total FROM person_statement s WHERE s.sheet_id = person.sheet_id"
518	                + " AND s.person_id = person.id AND s.seq = person.statement_count - 1),"
519	                + " statement_date = (SELECT s.statement_date FROM person_statement s WHERE s.sheet_id = person.sheet_id"
520	                + " AND s.person_id = person.id AND s.seq = person.statement_count - 1)"
521	                + " WHERE id = ? AND sheet_id = ? AND statement_count > 0", id, sheetId);
522	    }
523	
524	    /** Retire a person from a date. */
525	    public void retire(String sheetId, long id, LocalDate from) {
526	        jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND sheet_id = ?", Date.valueOf(from), id, sheetId);
527	        history.retire(sheetId, id, from);
528	    }
529	
530	    /** Put a person on hold from a from-date to a to-date (null: open-ended). */
531	    public void hold(String sheetId, long id, LocalDate from, LocalDate to) {
532	        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, held_on)"
533	                + " SELECT ?, ?, ?, ?, today FROM sheet WHERE id = ?",
534	                sheetId, id, Date.valueOf(from), to == null ? null : Date.valueOf(to), sheetId);
535	    }
536	
537	    /** Refuse a claim of the person dated after the date they are retired from. */
538	    public void claimAllowed(String sheetId, long id, LocalDate date) throws BadRequestException {
539	        Person p = find(sheetId, id);
540	        if (p != null && p.retiredFrom() != null && date.isAfter(LocalDate.parse(p.retiredFrom()))) {
541	            throw new BadRequestException(p.name() + " is retired from " + p.retiredFrom());
542	        }
543	    }
544	
545	    /** Whether another person on the sheet (other than {@code exceptId}; 0 for none) already has this name, ignoring case. */
546	    public boolean nameTaken(String sheetId, String name, long exceptId) {
547	        Integer taken = jdbc.queryForObject(
548	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(name) = LOWER(?) AND id <> ?",
549	                Integer.class, sheetId, name, exceptId);
550	        return taken != null && taken > 0;
551	    }
552	
553	    /** The person on the sheet with this name, ignoring case; null when there is none. */
554	    public Person findByName(String sheetId, String name) {
555	        List<Person> found = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND LOWER(name) = LOWER(?)",
556	                ROW, sheetId, name);
557	        return found.isEmpty() ? null : found.get(0);
558	    }
559	
560	    /** Whether another person on the sheet (other than {@code exceptId}; 0 for none) already has this contact. */
561	    public boolean contactTaken(String sheetId, String contact, long exceptId) {
562	        Integer taken = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ? AND id <> ?",
563	                Integer.class, sheetId, contact, exceptId);
564	        return taken != null && taken > 0;
565	    }
566	
567	    public Person add(String sheetId, String name, String grade, Integer terms) {
568	        return add(sheetId, name, grade, terms, null);
569	    }
570	
571	    /** Add a person with their own terms and contact (each null: none). */
572	    public Person add(String sheetId, String name, String grade, Integer terms, String contact) {
573	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
574	        jdbc.update(c -> {
575	            PreparedStatement ps = c.prepareStatement(
576	                    "INSERT INTO person (sheet_id, name, grade, terms, contact, added_on)"
577	                            + " SELECT ?, ?, ?, ?, ?, today FROM sheet WHERE id = ?", new String[] { "id" });
578	            ps.setString(1, sheetId);
579	            ps.setString(2, name);
580	            ps.setString(3, grade);
581	            ps.setObject(4, terms, java.sql.Types.INTEGER);
582	            ps.setString(5, contact);
583	            ps.setString(6, sheetId);
584	            return ps;
585	        }, keys);
586	        long id = keys.getKey().longValue();
587	        grade(sheetId, id, grade, null);
588	        return new Person(id, name, grade, 1, 0, null, null, null, false, List.of(new GradeFrom(grade, null)), List.of(), terms, contact);
589	    }
590	
591	    /** Whether the sheet has this person. */
592	    public boolean exists(String sheetId, long id) {
593	        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM person WHERE id = ? AND sheet_id = ?",
594	                Integer.class, id, sheetId);
595	        return known != null && known > 0;
596	    }
597	
598	    public boolean update(String sheetId, long id, long version, String name, Integer terms) {
599	        return jdbc.update(
600	                "UPDATE person SET name = ?, terms = ?, version = version + 1 WHERE id = ? AND sheet_id = ? AND version = ?",
601	                name, terms, id, sheetId, version) > 0;
602	    }
603	
604	    /** Change a person's name, own terms and contact (each null: none), if they are still at {@code version}, moving them to the next version;
605	     *  false when the sheet has no such person at that version. Their grades are given by {@link #grade}. */
606	    public boolean update(String sheetId, long id, long version, String name, Integer terms, String contact) {
607	        return jdbc.update(
608	                "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE id = ? AND sheet_id = ? AND version = ?",
609	                name, terms, contact, id, sheetId, version) > 0;
610	    }
611	}
612	package net.officefloor.hq.app.person;
613	
614	import java.util.List;
615	
616	/** A person on a sheet: the id the store assigned, their name and the grade (A, B or C) in force on
617	 *  the sheet's today, with every grade they have been given (oldest first), and the
618	 *  version of these values (up by one on each save), and their statements: how many have been taken,
619	 *  and the last one's due-total and date (both null before the first), and the date they are retired
620	 *  from (null when not retired; any date set means retired at once), and their holds (oldest first) and
621	 *  whether they have any (their open (OPEN or PENDING) claims dated within a hold, unless bound by a
622	 *  statement, then count in no live total), and their own terms in days (null when they have none), and their contact (null when they have none). */
623	public record Person(long id, String name, String grade, long version, long statementCount,
624	        String statedTotal, String statementDate, String retiredFrom, boolean held, List<GradeFrom> grades,
625	        List<Hold> holds, Integer terms, String contact) {
626	
627	    public Person withGrades(List<GradeFrom> grades) {
628	        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds, terms, contact);
629	    }
630	
631	    public Person withHolds(List<Hold> holds) {
632	        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom,
633	                !holds.isEmpty(), grades, holds, terms, contact);
634	    }
635	
636	    public boolean retired() {
637	        return retiredFrom != null;
638	    }
639	
640	    /** Their holds as they act on live totals on the sheet's today: once their retirement date is reached
641	     *  (the sheet's today on or after it) they are held over every date as well. */
642	    public List<Hold> liveHolds(String today) {
643	        if (retiredFrom == null || today == null || retiredFrom.compareTo(today) > 0) return holds;
644	        List<Hold> all = new java.util.ArrayList<>(holds);
645	        all.add(new Hold(null, null));
646	        return all;
647	    }
648	}
