651	import java.util.List;
652	
653	/** One of a person's holds: from its from-date to its to-date (yyyy-mm-dd, both inclusive; a null
654	 *  from-date is the beginning of time, a null to-date open-ended). */
655	public record Hold(String from, String to) {
656	
657	    /** Whether the hold covers this date (yyyy-mm-dd). */
658	    public boolean covers(String date) {
659	        return (from == null || from.compareTo(date) <= 0) && (to == null || to.compareTo(date) >= 0);
660	    }
661	
662	    /** Whether any of these holds covers this date. */
663	    public static boolean anyCovers(List<Hold> holds, String date) {
664	        return holds.stream().anyMatch(h -> h.covers(date));
665	    }
