package net.officefloor.hq.app.claim;


public class SaveClaim {
    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            @Val ClaimInput input, ServerHttpConnection connection, ClaimRepository repository,
            SheetRepository sheets, PeriodRepository periods, PersonRepository people, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long cid;
        try {
            cid = Long.parseLong(claimId == null ? "" : claimId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such claim");
        }
        Claim found = repository.find(id, cid);
        if (found == null) {
            throw new BadRequestException("no such claim");
        }
        // Only a draft can be edited: to change an open claim, void it and add a new one.
        if (!found.status().equals("DRAFT")) {
            throw new BadRequestException("a " + found.status() + " claim cannot be edited");
        }
        String holder = repository.lockedBy(id, cid);
        if (holder != null && !holder.equals(by)) {
            throw new BadRequestException("the claim is being edited by " + holder);
        }
        LocalDate date = input.date() != null ? input.date() : sheets.today(id);
        PeriodGuard.open(periods, id, LocalDate.parse(found.dueBy()));
        people.claimAllowed(id, found.personId(), date);
        input.checkCorrection(repository, id, found.personId());
        input.checkRef(repository, id, cid);
        // A draft's due-by follows its date: changing the date fixes the due-by afresh from the new one.
        String dueBy = date.toString().equals(found.date()) ? found.dueBy() : repository.dueBy(id, found.personId(), date).toString();
        Rollup.Snapshot before = rollup.take(id);
        if (!repository.update(id, cid, input.amount(), date, LocalDate.parse(dueBy), input.note(), input.corrects(), input.ref(), input.tags())) {
            throw new BadRequestException("only a DRAFT claim can be edited");
        }
        repository.editedBy(id, cid, by);
        repository.unlock(id, cid, by);
        long pid = found.personId();
        Claim saved = new Claim(cid, pid, ClaimRepository.money(input.amount()), date.toString(), input.note(),
                found.status(), found.number(), found.due(), found.openedBy(), found.stated(), found.statedDue(), input.corrects(),
                dueBy, found.statedNa(), found.deferredUntil(), found.deferred(), found.proofs(), found.splitFrom(), found.lateEntry(), found.reminded(), input.ref(), input.tags(), found.voidReason());
        audit.record("CLAIM_EDITED sheet=" + id + " by=" + by + " person=" + repository.personName(id, pid)
                + " amount=" + saved.amount() + " date=" + saved.date() + Claim.auditNumber(saved.number()));
        rollup.record(id, by, before);
        claim.set(saved);
    }
}
=== claim/BulkSettleClaims.java
package net.officefloor.hq.app.claim;


/** Settle the selected claims together, all or nothing: when any of them cannot be settled by the signed-in
 *  user (any refusal the single settle would give; going to PENDING is not one), none is settled, every one
 *  counts as refused and nothing is written. Otherwise each is settled in list order (people in the order they
 *  were added, each person's claims newest first) by exactly the rules of settling one claim (a claim a clerk
 *  sends to PENDING counts as settled); they are the sheet's next batch, each keeps its number, and after the
 *  claims' own lines BATCH_SETTLED batch=<n> count=<claims> total=<the frozen dues of those SETTLED> is written. */
public class BulkSettleClaims {
    public void settle(@PathVariable("sheetId") String sheetId, @RequestBody BulkSettleRequest request,
            ServerHttpConnection connection, ClaimRepository repository, PeriodRepository periods,
            SettingsRepository settings, Audit audit, Rollup rollup, WatchRepository watches, Out<BulkSettleResult> result) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        Set<Long> selected = new LinkedHashSet<>();
        if (request != null && request.claimIds() != null) {
            for (Long cid : request.claimIds()) {
                if (cid != null) selected.add(cid);
            }
        }
        if (selected.isEmpty()) {
            throw new BadRequestException("select at least one claim");
        }
        List<Claim> found = repository.inListOrder(id, selected);
        boolean refusedAny = found.size() < selected.size();
        for (Claim c : found) {
            if (refusedAny) break;
            try {
                ClaimStatusChange.check(id, c.id(), "settle", by, repository, periods, settings);
            } catch (BadRequestException e) {
                refusedAny = true;
            }
        }
        if (refusedAny) {
            result.set(new BulkSettleResult(0, selected.size()));
            return;
        }
        List<Long> settled = new ArrayList<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : found) {
            Claim changed = ClaimStatusChange.apply(id, c.id(), "settle", by, repository, periods, settings, audit, rollup, watches);
            settled.add(c.id());
            if ("SETTLED".equals(changed.status()) && changed.due() != null) {
                total = total.add(new BigDecimal(changed.due()));
            }
        }
        int batch = repository.batch(id, settled);
