import { counts, fixedDue, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { settingOn, useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { hundredths, money, rateFor, sumDues, useRates } from './useRates';

/** Each person's due-total, by person id: the sum of the figures of their claims that count (open (OPEN or PENDING)
 *  claims dated within one of their holds left out unless a statement binds them; a settled claim's frozen due, else the figure their last statement
 *  bound it to, else its live due, with its late charge while overdue),
 *  skipping those with none; 'n/a' when no rate for the grade they have on the sheet's today is in force
 *  then and no counting claim of theirs keeps a fixed figure or has a due (at the grade it was claimed under).
 *  A due-total is at most the sheet's cap in force on its today ('n/a' is not capped). */
export function useDueTotals(sheetId: string): Map<number, string> {
  const totals = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) totals.set(id, f.total);
  return totals;
}

/** Each person's excess, by person id: how far the sum of their figures is above the sheet's cap; 0.00 when
 *  it is not (or there is no cap, or their due-total is 'n/a'). */
export function useExcess(sheetId: string): Map<number, string> {
  const excess = new Map<number, string>();
  for (const [id, f] of useDueFigures(sheetId)) excess.set(id, f.excess);
  return excess;
}

/** Each person's settled-total and open-total, by person id: the sum of the figures of their counting SETTLED
 *  claims, and of their counting open (OPEN or PENDING) claims, as in their due-total ('n/a' figures skipped).
 *  The two add up to the due-total before the cap. */
export function useSettledOpenTotals(sheetId: string): Map<number, { settled: string; open: string }> {
  const split = new Map<number, { settled: string; open: string }>();
  for (const [id, f] of useDueFigures(sheetId)) split.set(id, { settled: f.settled, open: f.open });
  return split;
}

/** Each person's due-total held to the cap, their excess over it, and its settled and open parts. */
function useDueFigures(sheetId: string): Map<number, { total: string; excess: string; settled: string; open: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const settings = useSettings(sheetId).data;
  const holds = holdsById(people.data, today.data?.today);
  const cap = settingOn(settings, 'cap', today.data?.today);
  const totals = new Map<number, { total: string; excess: string; settled: string; open: string }>();
  for (const p of people.data ?? []) {
    const counting = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c, holds, today.data?.today));
    const rated = rateFor(rates.data, p.grade, today.data?.today) !== undefined;
    const dues = counting.map((c) =>
      claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings, today.data?.today, gradeOn(p, c.date)));
    const shown = rated || counting.some((c) => fixedDue(c) !== null && fixedDue(c) !== 'n/a') || dues.some((d) => d !== 'n/a');
    const sum = sumDues(dues);
    const over = shown && cap !== null && hundredths(sum) > hundredths(cap);
    totals.set(p.id, {
      total: !shown ? 'n/a' : over ? cap : sum,
      excess: over ? money(hundredths(sum) - hundredths(cap)) : '0.00',
      settled: sumDues(dues.filter((_, i) => counting[i].status === 'SETTLED')),
      open: sumDues(dues.filter((_, i) => counting[i].status !== 'SETTLED')),
    });
  }
  return totals;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-mm-dd; null when it
 *  applies from the beginning of time) through its to-date (null when it has no end). */
export type Rate = { grade: string; pct: string; from: string | null; to: string | null };

export function ratesKey(sheetId: string) {
  return ['sheet', sheetId, 'rates'];
}

/** The sheet's rates, by grade then from-date (an undated rate first); a grade with no rate is not
 *  listed. */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: async () =>
      (await getJson<{ rates: Rate[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`)).rates,
  });
}

/** The rate (a two-decimal percent) for a grade in force on a date (yyyy-mm-dd): the one with the
 *  latest from-date on or before it, an undated rate applying from the beginning of time; undefined
 *  when none applies, or the date is after that rate's to-date. */
export function rateFor(rates: Rate[] | undefined, grade: string | undefined, on: string | undefined): string | undefined {
  if (on === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > on)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  if (found?.to != null && found.to < on) return undefined;
  return found?.pct;
}

/** A two-decimal number as a whole count of hundredths ("12.50" -> 1250, "-0.30" -> -30). */
export function hundredths(v: string): bigint {
  const t = v.trim();
  const negative = t.startsWith('-');
  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

/** A whole count of hundredths as a two-decimal number (-30 -> "-0.30"). */
export function money(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/** A rate figure: an amount (two decimals) times a rate (a two-decimal percent), divided by 100, rounded
 *  half up (when `halfUp`) or half to even to two decimals — not floored (see `atLeast`); 'n/a' when there is
 *  no rate. Worked in whole numbers, so exact. */
export function due(amount: string, pct: string | undefined, halfUp: boolean): string {
  if (pct === undefined) return 'n/a';
  return money(percentOf(amount, pct, 1n, halfUp));
}

/** A figure (two decimals) raised to at least a floor (two decimals; none when undefined); 'n/a' stays 'n/a'. */
export function atLeast(figure: string, floor: string | undefined): string {
  if (figure === 'n/a' || floor === undefined || hundredths(figure) >= hundredths(floor)) return figure;
  return money(hundredths(floor));
}

/** Whether an amount (two decimals) is a correction's: below zero. */
export function isCorrection(amount: string): boolean {
  return hundredths(amount) < 0n;
}

/** An amount (two decimals) times a rate (a two-decimal percent) times a whole number, divided by
 *  100, rounded half up (when `halfUp`, away from zero) or half to even, in hundredths (a negative amount rounds as its size does, then takes
 *  its sign back). */
function percentOf(amount: string, pct: string, times: bigint, halfUp: boolean): bigint {
  const signed = hundredths(amount) * hundredths(pct) * times; // in 1/1_000_000 of a unit
  const product = signed < 0n ? -signed : signed;
  const rest = product % 10000n;
  let cents = product / 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return signed < 0n ? -cents : cents;
}

/** A figure (two decimals) with a late charge added on top: for each full 30 days, the late percent
 *  (two decimals) in force on that boundary of the figure plus the charges of the boundaries before it (compounding), each rounded like a due, the charges added up;
 *  'n/a' stays 'n/a'. */
export function withCharge(figure: string, latePcts: string[], halfUp: boolean): string {
  if (figure === 'n/a') return figure;
  return money(latePcts.reduce((sum, pct) => sum + percentOf(money(sum), pct, 1n, halfUp), hundredths(figure)));
}

/** Dues added up, skipping 'n/a'. */
export function sumDues(dues: string[]): string {
  return money(dues.filter((d) => d !== 'n/a').reduce((sum, d) => sum + hundredths(d), 0n));
}

/** A sheet's total of people's figures: added up, skipping 'n/a', but leaving out the single highest
 *  and the single lowest figure when three or more people have one. */
export function trimmedSum(figures: string[]): string {
  const cents = figures.filter((d) => d !== 'n/a').map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = cents.length >= 3 ? cents.slice(1, -1) : cents;
  return money(kept.reduce((sum, c) => sum + c, 0n));
}
import { countsOn, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { rateFor, sumDues, useRates } from '../rates/useRates';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';
import { usePeriods } from './usePeriods';

/** Each person's due-total for each period, by person id then period name: the figures of their claims
 *  whose due-by falls in it that count by the status they had at the end of its last day (see `countsOn`) (a settled claim's frozen due, else the figure its last statement
 *  bound it to, else its live due, with its late charge while overdue), skipping those with none — the
 *  one fixed when the period was closed while it is closed or soft-closed (0.00 for a person added since). */
export function usePersonPeriodDueTotals(sheetId: string): Map<number, Map<string, string>> {
  const periods = usePeriods(sheetId);
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const holds = holdsById(people.data, today);
  const totals = new Map<number, Map<string, string>>();
  for (const person of people.data ?? []) {
    const own = (claims.data ?? []).filter((c) => c.personId === person.id);
    const byPeriod = new Map<string, string>();
    for (const p of periods.data ?? []) {
      byPeriod.set(
        p.name,
        p.closed || p.softClosed
          ? (p.personTotals[String(person.id)] ?? '0.00')
          : sumDues(
              own
                .filter((c) => p.from <= c.dueBy && c.dueBy <= p.to && countsOn(c, p.to, holds, today))
                .map((c) => claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(person, c.date), c.date), settings, today, gradeOn(person, c.date))),
            ),
      );
    }
    totals.set(person.id, byPeriod);
  }
  return totals;
}

/** Each period's due-total, by period name: the sum of the people's due-totals for it. */
export function usePeriodDueTotals(sheetId: string): Map<string, string> {
  const periods = usePeriods(sheetId);
  const perPerson = [...usePersonPeriodDueTotals(sheetId).values()];
  const totals = new Map<string, string>();
  for (const p of periods.data ?? []) {
    totals.set(p.name, sumDues(perPerson.map((byPeriod) => byPeriod.get(p.name) ?? '0.00')));
  }
  return totals;
}
import type { Claim } from '../claims/useClaims';

/** The statuses the summary counts; no claim is PENDING today, so its count stays 0. */
export const STATUSES: string[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** How many of these claims have a status. */
export function countWithStatus(claims: readonly Claim[] | undefined, status: string): number {
  return (claims ?? []).filter((c) => c.status === status).length;
}
import { counts, fixedDue, isDeferred, isOpen, useClaims, type Claim } from '../claims/useClaims';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { atLeast, due, isCorrection, rateFor, sumDues, useRates, withCharge } from '../rates/useRates';
import { settingOn, useSettings, type Settings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';

/** The day (yyyy-mm-dd) a claim's overdue days count from: its due-by plus the grace days, in force on the claim's
 *  date, of the grade its person had on that date (`grade`); its due-by when that grade has none then. */
export function overdueFrom(c: Claim, settings: Settings | undefined, grade: string | undefined): string {
  const grace = grade === undefined ? null : settingOn(settings, `grace-${grade}`, c.date);
  if (grace === null || grace === '') return c.dueBy;
  return new Date(Date.parse(`${c.dueBy}T00:00:00Z`) + Number(grace) * 86_400_000).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and its overdue-from day (see
 *  `overdueFrom`; `grade` is the grade its person had on its date) is before the sheet's today. */
export function isOverdue(c: Claim, today: string, settings: Settings | undefined, grade: string | undefined): boolean {
  return isOpen(c) && !isDeferred(c, today) && overdueFrom(c, settings, grade) < today;
}

/** Whether a claim's live figures (its rate step and late charge) round half up: when the claim is
 *  dated before the sheet's policy date (blank meaning the sheet's today); else they round half to
 *  even. A correction rounds by the date of the claim it corrects (its person's claim with that
 *  number), not its own. Half to even until the settings and the sheet's today are loaded. */
export function roundsHalfUp(c: Claim, claims: Claim[] | undefined, settings: Settings | undefined, today: string | undefined): boolean {
  const policy = settings === undefined ? undefined : settings.policyDate ?? today;
  if (policy === undefined) return false;
  const corrected = c.corrects === null
    ? undefined
    : (claims ?? []).find((o) => o.personId === c.personId && o.number === c.corrects);
  return (corrected?.date ?? c.date) < policy;
}

/** A claim's due now: a settled claim's frozen due; else the greater of the floor (two decimals; none while
 *  it is not loaded) and its figure (the one its last statement bound it to, else its live rate figure) plus,
 *  while it is overdue, for every full 30 days it is overdue the sheet's late percent in force on that boundary
 *  date (the overdue-from day — the due-by plus the grade's grace — plus 30, 60, 90 ... days) of that figure plus the charges of the boundaries before it (compounding), each rounded like a due, the charges added up. The
 *  charge is never bound by a statement: it follows the sheet's today until settling freezes it in. A correction
 *  (a negative amount) has no floor and no late charge. No charge until the settings and the sheet's today are loaded. */
export function dueNow(c: Claim, figure: string, floor: string | undefined, settings: Settings | undefined,
  today: string | undefined, halfUp: boolean, grade: string | undefined): string {
  if (c.due !== null || figure === 'n/a' || isCorrection(c.amount)) return figure;
  const pcts: string[] = [];
  if (settings !== undefined && today !== undefined && isOverdue(c, today, settings, grade)) {
    const dueBy = Date.parse(`${overdueFrom(c, settings, grade)}T00:00:00Z`);
    const periods = Math.floor((Date.parse(`${today}T00:00:00Z`) - dueBy) / 86_400_000 / 30);
    for (let n = 1; n <= periods; n++) {
      const boundary = new Date(dueBy + n * 30 * 86_400_000).toISOString().slice(0, 10);
      pcts.push(settingOn(settings, 'late-pct', boundary) ?? '0.00');
    }
  }
  return atLeast(withCharge(figure, pcts, halfUp), floor);
}

/** A claim's due now (see `dueNow`) from its fixed figure, else its live rate figure at this rate (a
 *  two-decimal percent; undefined when none applies), with the floor in force on its date, every rounding by
 *  the claim's policy (see `roundsHalfUp`) — the other claims on the sheet are what a correction is looked up in.
 *  No floor until the settings are loaded. */
export function claimDueNow(c: Claim, claims: Claim[] | undefined, pct: string | undefined,
  settings: Settings | undefined, today: string | undefined, grade: string | undefined): string {
  const up = roundsHalfUp(c, claims, settings, today);
  const floor = settings === undefined ? undefined : settingOn(settings, 'floor', c.date) ?? undefined;
  return dueNow(c, fixedDue(c) ?? due(c.amount, pct, up), floor, settings, today, up, grade);
}

/** Each person's overdue figures, by person id: how many of their claims that count are overdue, and
 *  the sum of those claims' dues now (a stated claim's bound figure, else its live due, with its late
 *  charge), skipping
 *  those with none. Empty until the terms and the sheet's today are loaded. */
export function useOverdue(sheetId: string): Map<number, { count: number; total: string }> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const holds = holdsById(people.data, today);
  const figures = new Map<number, { count: number; total: string }>();
  if (settings === undefined || today === undefined) return figures;
  for (const p of people.data ?? []) {
    const overdue = (claims.data ?? []).filter(
      (c) => c.personId === p.id && counts(c, holds, today) && isOverdue(c, today, settings, gradeOn(p, c.date)),
    );
    figures.set(p.id, {
      count: overdue.length,
      total: sumDues(overdue.map((c) =>
        claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings, today, gradeOn(p, c.date)))),
    });
  }
  return figures;
}
import { counts, isOpen, useClaims } from '../claims/useClaims';
import { claimDueNow } from '../overdue/useOverdue';
import { gradeOn, holdsById, usePeople } from '../people/usePeople';
import { rateFor, sumDues, useRates } from '../rates/useRates';
import { useSettings } from '../settings/useSettings';
import { useSheetToday } from '../today/useSheetToday';

export type Aging = { d0to30: string; d31to60: string; d61: string };

/** A claim's age on the sheet's today: the days from its date; 0 for a claim dated after today. */
export function ageDays(date: string, today: string): number {
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${date}T00:00:00Z`)) / 86_400_000;
  return Math.max(0, Math.round(days));
}

/** Each person's aging, by person id: the sum of the dues now of their OPEN and PENDING claims that count,
 *  split by the claim's age (0 to 30 days, 31 to 60, 61 or more), skipping those with none.
 *  Empty until the sheet's today is loaded. */
export function useAging(sheetId: string): Map<number, Aging> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId).data;
  const today = useSheetToday(sheetId).data?.today;
  const holds = holdsById(people.data, today);
  const aging = new Map<number, Aging>();
  if (today === undefined) return aging;
  for (const p of people.data ?? []) {
    const buckets: [string[], string[], string[]] = [[], [], []];
    for (const c of claims.data ?? []) {
      if (c.personId !== p.id || !isOpen(c) || !counts(c, holds, today)) continue;
      const age = ageDays(c.date, today);
      const d = claimDueNow(c, claims.data, rateFor(rates.data, gradeOn(p, c.date), c.date), settings, today, gradeOn(p, c.date));
      buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2].push(d);
    }
    aging.set(p.id, { d0to30: sumDues(buckets[0]), d31to60: sumDues(buckets[1]), d61: sumDues(buckets[2]) });
  }
  return aging;
}
import { counts, isOpen, useClaims } from '../claims/useClaims';
import { holdsById, usePeople } from '../people/usePeople';
import { useSheetToday } from '../today/useSheetToday';

/** The first day (yyyy-mm-dd) of the 30 days up to and including a day. */
function windowStart(today: string): string {
  return new Date(Date.parse(`${today}T00:00:00Z`) - 29 * 86_400_000).toISOString().slice(0, 10);
}

/** Whether each person is active, by person id: they have an open (OPEN or PENDING) claim that counts
 *  (see `counts`) dated within the 30 days up to and including the sheet's today. */
