import { useCallback, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { claimsKey } from '../claims/useClaims';
import { peopleKey, usePeople, type Person } from '../people/usePeople';
import { usePersonRowAction } from '../people/usePersonRowAction';

/** A person's statements: how many have been taken, the last one's due-total and date (blank before
 *  the first), and a button that takes one. Taking a statement records their due-total and binds each
 *  of their counting claims to the figure it has then (unbinding the rest), until the next one; a
 *  steward can cancel the last one, its claims going live again. A date beside the button takes the
 *  statement as of that date (on or before the sheet's today; blank: now); it is cleared once that statement is
 *  taken or refused. */
function PersonStatement({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const p = people.data?.find((x) => x.id === personId);
  const [asof, setAsof] = useState('');

  const take = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/statement`, { asof: date }),
    // The date is for the one statement it was typed for: taken or refused, the next one is now unless a
    // date is typed again.
    onSettled: () => setAsof(''),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });
  const unstate = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/unstate`, {}),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });
  const { reset: resetTake } = take;
  const { reset: resetUnstate } = unstate;
  const reset = useCallback(() => {
    resetTake();
    resetUnstate();
  }, [resetTake, resetUnstate]);
  const announce = usePersonRowAction(sheetId, personId, reset);
  const error = take.error ?? unstate.error;

  return (
    <>
      <td data-testid="person-statement-count">{p?.statementCount ?? 0}</td>
      <td data-testid="person-stated-total">{p?.statedTotal ?? ''}</td>
      <td data-testid="person-statement-date">{p?.statementDate ?? ''}</td>
      <td>
        <input
          type="text"
          placeholder="yyyy-mm-dd"
          data-testid="person-statement-asof"
          aria-label="Statement as of"
          value={asof}
          onChange={(e) => {
            setAsof(e.target.value);
            reset();
          }}
        />
        <button
  const error = close.error ?? softClose.error ?? reopen.error;
  const act = (m: { mutateAsync: () => Promise<Period> }) =>
    closeOnce(() => {
      close.reset();
      softClose.reset();
      reopen.reset();
      return m.mutateAsync();
    });

  return (
    <tr data-testid={`period-row-${p.name}`}>
      <td data-testid="period-name">{p.name}</td>
      <td data-testid="period-from">{p.from}</td>
      <td data-testid="period-to">{p.to}</td>
      <td data-testid="period-due-total">{dueTotal}</td>
      <td data-testid="period-closed">{p.closed ? 'yes' : p.softClosed ? 'soft' : 'no'}</td>
      <td>
        <button
          type="button"
          data-testid="period-close"
          disabled={close.isPending}
          onClick={() => act(close)}
        >
          Close
        </button>{' '}
        <button
          type="button"
          data-testid="period-soft-close"
          disabled={softClose.isPending}
          onClick={() => act(softClose)}
        >
          Soft close
        </button>{' '}
        <button
          type="button"
          data-testid="period-reopen"
          disabled={reopen.isPending}
          onClick={() => act(reopen)}
        >
          Reopen
        </button>
        {error && <span data-testid="period-error">{error.message}</span>}
      </td>
    </tr>
  );
}

/** A column per period on the people list. */
function PeriodColumnHeads({ sheetId }: { sheetId: string }) {
  const periods = usePeriods(sheetId);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <th key={p.id}>Due {p.name}</th>
      ))}
    </>
  );
}

/** A person's due-total for each period on the sheet (fixed while the period is closed). */
function PersonPeriodDueTotals({ sheetId, personId }: { sheetId: string; personId: number }) {
  const periods = usePeriods(sheetId);
  const totals = usePersonPeriodDueTotals(sheetId).get(personId);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <td key={p.id} data-testid={`person-period-${p.name}-due-total`}>
          {totals?.get(p.name) ?? ''}
        </td>
      ))}
    </>
  );
}

export const contributions = [
  SheetBody.fill({ order: 6, Component: ({ sheetId }) => <Periods sheetId={sheetId} /> }),
  PersonColumnHead.fill({ order: 22, Component: PeriodColumnHeads }),
  PersonCells.fill({ order: 22, Component: PersonPeriodDueTotals }),
];

