58	/** Bind the paste box: each non-blank line is name,amount,date,note — the name is required (trimmed), the
59	 *  amount and date follow the claim form's rules (a blank date: the sheet's entry date, else its today), and the note is the rest
60	 *  of the line (it may hold commas, or be absent); a note ending in " #<reference>" gives the claim that external reference. A paste with no lines is refused. */
61	public class ValidatePaste {
62	    /** A note ending in " #<reference>": the note before it, and the reference. */
63	    private static final Pattern REF = Pattern.compile("(.*) #(\\S.*)");
64	    public void validate(@RequestBody PasteRequest request, Out<PasteInput> paste) throws BadRequestException {
65	        String text = request == null || request.text() == null ? "" : request.text();
66	        List<PasteLine> lines = new ArrayList<>();
67	        int n = 0;
68	        for (String raw : text.split("\r?\n", -1)) {
69	            n++;
70	            if (raw.isBlank()) {
71	                continue;
72	            }
73	            String[] f = raw.split(",", 4);
74	            String name = f[0].trim();
75	            String amount = f.length > 1 ? f[1].trim() : "";
76	            String date = f.length > 2 ? f[2].trim() : "";
77	            String note = f.length > 3 ? f[3].trim() : "";
78	            String ref = null;
79	            Matcher tail = REF.matcher(note);
80	            if (tail.matches()) {
81	                note = tail.group(1).trim();
82	                ref = tail.group(2).trim();
83	            }
84	            if (name.isEmpty()) {
85	                throw new BadRequestException("line " + n + ": name is required");
86	            }
87	            LocalDate on = null;
88	            if (!date.isEmpty()) {
89	                try {
90	                    on = LocalDate.parse(date);
91	                } catch (DateTimeParseException e) {
92	                    throw new BadRequestException("line " + n + ": date must be yyyy-mm-dd");
93	                }
94	            }
95	            try {
96	                lines.add(new PasteLine(name, new ClaimInput(ClaimInput.signedAmount(amount), on, note, null, ref, null)));
97	            } catch (BadRequestException e) {
98	                throw new BadRequestException("line " + n + ": " + e.getMessage());
99	            }
100	        }
101	        if (lines.isEmpty()) {
102	            throw new BadRequestException("paste at least one line");
103	        }
